import math
def count_for_n(n, m, target):
    total_count = 0
    if target <= m:
        total_count += 1
    for k in range(1, m):
        a_start = (-target) % (k + 1)
        if a_start == 0:
            a_start = k + 1
        max_a = (target - 1 - k) // k
        if a_start <= max_a:
            for a in range(a_start, max_a + 1, k + 1):
                b = (target - a*k) // (k+1)
                if math.gcd(a, b) == 1:
                    dist = 0
                    temp_a, temp_b = a, b
                    while temp_b != 0:
                        dist += temp_a // temp_b
                        temp_a, temp_b = temp_b, temp_a % temp_b
                    if dist <= n:
                        total_count += 1
    return total_count

